def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        return 'C'
    if n == 3:
        if history[2][1] == 'C':
            return 'D'
        return 'C'
    if n == 99:
        return 'D'
    opp_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
    if opp_c == n:
        return 'D'
    last_me, last_opp = history[-1]
    if last_opp == 'D':
        if last_me == 'D':
            dd = 0
            for a, b in reversed(history):
                if a == 'D' and b == 'D':
                    dd += 1
                else:
                    break
            recent_opp_c = 0
            for a, b in history[-10:]:
                if b == 'C':
                    recent_opp_c += 1
            if dd >= 2 and recent_opp_c >= 3:
                return 'C'
            return 'D'
        return 'D'
    if last_me == 'D':
        return 'C'
    return 'C'
